INSERT INTO public.restaurant_templates (key, nombre, descripcion, payload, activo, version)
VALUES ('almuerzos', 'Almuerzos / Corrientazo / Ejecutivos', 'Restaurante de almuerzo del día con precio fijo: sopa, principio, proteína, acompañantes y jugo que se eligen o rotan cada mañana.', $json${"categorias":[{"value":"almuerzos","label":"Almuerzos del día","emoji":"🍛"},{"value":"ejecutivos","label":"Ejecutivos","emoji":"💼"},{"value":"platos_especiales","label":"Platos especiales","emoji":"🍗"},{"value":"sopas","label":"Sopas","emoji":"🥣"},{"value":"bebidas","label":"Bebidas y jugos","emoji":"🥤"},{"value":"adicionales","label":"Adicionales","emoji":"➕"},{"value":"postres","label":"Postres","emoji":"🍮"}],"listas":[{"key":"sopas_del_dia","nombre":"Sopas del día","items":[{"label":"Sopa de lentejas","precio_extra":0},{"label":"Sopa de fríjoles","precio_extra":0},{"label":"Sancocho","precio_extra":0},{"label":"Consomé","precio_extra":0},{"label":"Sopa de pasta","precio_extra":0},{"label":"Crema de verduras","precio_extra":0}]},{"key":"principios","nombre":"Principios del día","items":[{"label":"Fríjoles","precio_extra":0},{"label":"Lentejas","precio_extra":0},{"label":"Garbanzos","precio_extra":0},{"label":"Habichuelas","precio_extra":0},{"label":"Pasta","precio_extra":0},{"label":"Verdura salteada","precio_extra":0}]},{"key":"proteinas_almuerzos","nombre":"Proteínas","items":[{"label":"Pollo sudado","precio_extra":0},{"label":"Pechuga a la plancha","precio_extra":0},{"label":"Pollo frito","precio_extra":0},{"label":"Carne de res","precio_extra":0},{"label":"Carne sudada","precio_extra":0},{"label":"Carne asada","precio_extra":0},{"label":"Carne molida","precio_extra":0},{"label":"Chuleta de cerdo","precio_extra":0},{"label":"Carne de cerdo","precio_extra":0},{"label":"Mojarra frita","precio_extra":0},{"label":"Pescado","precio_extra":0},{"label":"Hígado","precio_extra":0},{"label":"Chicharrón","precio_extra":0},{"label":"Chorizo","precio_extra":0}]},{"key":"acompanantes_almuerzos","nombre":"Harina / acompañante","items":[{"label":"Papa","precio_extra":0},{"label":"Yuca","precio_extra":0},{"label":"Plátano maduro","precio_extra":0},{"label":"Plátano verde (patacón)","precio_extra":0},{"label":"Papa a la francesa","precio_extra":0},{"label":"Bollo","precio_extra":0},{"label":"Arepa","precio_extra":0}]},{"key":"arroz_ensalada","nombre":"Arroz y ensalada","items":[{"label":"Arroz blanco","precio_extra":0},{"label":"Ensalada","precio_extra":0}]},{"key":"jugos_del_dia","nombre":"Jugos y bebidas del día","items":[{"label":"Jugo del día","precio_extra":0},{"label":"Limonada","precio_extra":0},{"label":"Jugo de mora","precio_extra":0},{"label":"Jugo de lulo","precio_extra":0},{"label":"Jugo de maracuyá","precio_extra":0},{"label":"Agua de panela","precio_extra":0}]},{"key":"postres","nombre":"Postres","items":[{"label":"Postre del día","precio_extra":0},{"label":"Porción de fruta","precio_extra":0}]}],"grupos_tipicos":[{"id":"g_sopa","nombre":"Sopa","modo":"single","min":0,"max":1,"requerido":false,"fuente":{"lista":"sopas_del_dia"}},{"id":"g_principio","nombre":"Principio","modo":"single","min":1,"max":1,"requerido":true,"fuente":{"lista":"principios"}},{"id":"g_proteina","nombre":"Proteína","modo":"single","min":1,"max":1,"requerido":true,"fuente":{"lista":"proteinas_almuerzos"}},{"id":"g_acompanante","nombre":"Harina / acompañante","modo":"multi","min":0,"max":2,"requerido":false,"fuente":{"lista":"acompanantes_almuerzos"}},{"id":"g_arroz_ensalada","nombre":"Arroz y ensalada","modo":"multi","min":0,"max":2,"requerido":false,"fuente":{"lista":"arroz_ensalada"}},{"id":"g_jugo","nombre":"Jugo","modo":"single","min":1,"max":1,"requerido":true,"fuente":{"lista":"jugos_del_dia"}},{"id":"g_postre","nombre":"Postre","modo":"single","min":0,"max":1,"requerido":false,"fuente":{"lista":"postres"}},{"id":"g_para_llevar","nombre":"Servicio","modo":"single","min":1,"max":1,"requerido":true,"fuente":{"items":[{"label":"Para comer aquí","precio_extra":0},{"label":"Para llevar","precio_extra":0}]}}],"platos_ejemplo":[{"nombre":"Almuerzo corriente completo","categoria":"almuerzos","precio":0,"grupos":["g_sopa","g_principio","g_proteina","g_acompanante","g_arroz_ensalada","g_jugo","g_para_llevar"]},{"nombre":"Almuerzo ejecutivo (sin sopa)","categoria":"ejecutivos","precio":0,"grupos":["g_principio","g_proteina","g_acompanante","g_arroz_ensalada","g_jugo","g_postre","g_para_llevar"]},{"nombre":"Almuerzo solo sopa y seco","categoria":"almuerzos","precio":0,"grupos":["g_sopa","g_proteina","g_acompanante","g_arroz_ensalada","g_jugo","g_para_llevar"]},{"nombre":"Bandeja paisa","categoria":"platos_especiales","precio":0,"grupos":["g_jugo","g_para_llevar"]},{"nombre":"Pechuga a la plancha","categoria":"platos_especiales","precio":0,"grupos":["g_acompanante","g_arroz_ensalada","g_jugo","g_para_llevar"]},{"nombre":"Sopa del día sola","categoria":"sopas","precio":0,"grupos":["g_sopa","g_para_llevar"]},{"nombre":"Jugo del día","categoria":"bebidas","precio":0,"grupos":["g_jugo"]},{"nombre":"Porción de principio del día","categoria":"adicionales","precio":0,"grupos":["g_principio"]}],"preguntas":[{"id":"p1","texto":"¿Cada mañana escribes un menú nuevo de sopas, principios y jugos, o repites un ciclo fijo por días de la semana?"},{"id":"p2","texto":"¿El precio del almuerzo cambia según la proteína que elija el cliente, por ejemplo res o pescado frente a pollo?"},{"id":"p3","texto":"¿El corrientazo y el ejecutivo son platos distintos en tu negocio? ¿En qué se diferencian?"},{"id":"p4","texto":"¿Qué elige el cliente en el almuerzo y qué viene fijo: solo la proteína, o también la sopa, el principio y el jugo?"},{"id":"p5","texto":"¿Cobras algo cuando el cliente repite sopa o jugo, o cuando pide el almuerzo para llevar con empaque?"},{"id":"p6","texto":"¿Se te agota la proteína durante la tarde? ¿Limitas cuántos platos de cada una vendes al día?"},{"id":"p7","texto":"¿Vendes almuerzos por mensualidad o a empresas con convenio, o fías a clientes de oficina?"}],"fuente":"docs/plantillas/almuerzos.md"}$json$::jsonb, false, 1)
