dores","g_hielo","g_acompanamiento"]},{"nombre":"Ron","categoria":"licores","precio":0,"grupos":["g_presentacion","g_mezcladores","g_hielo"]},{"nombre":"Whisky","categoria":"licores","precio":0,"grupos":["g_presentacion","g_mezcladores","g_hielo"]},{"nombre":"Tequila","categoria":"licores","precio":0,"grupos":["g_presentacion","g_acompanamiento"]},{"nombre":"Cerveza nacional","categoria":"cervezas","precio":0,"grupos":["g_tamano_cerveza","g_preparacion_cerveza"]},{"nombre":"Cerveza artesanal","categoria":"cervezas","precio":0,"grupos":["g_tamano_cerveza"]},{"nombre":"Cóctel de la casa","categoria":"cocteles_autor","precio":0,"grupos":["g_licor_base","g_sin_alcohol"]},{"nombre":"Mojito","categoria":"cocteles_clasicos","precio":0,"grupos":["g_licor_base","g_sin_alcohol"]},{"nombre":"Combo botella con mezcladores","categoria":"combos","precio":0,"grupos":["g_mezcladores","g_hielo"]},{"nombre":"Picada para compartir","categoria":"picadas","precio":0,"grupos":["g_porcion_picada"]}],"preguntas":[{"id":"p1","texto":"¿Cómo vendes los licores: por trago, media y botella? ¿Cada marca tiene su propio precio o manejas un solo precio por tipo de licor?"},{"id":"p2","texto":"Cuando vendes una botella o media, ¿los mezcladores, el hielo y las gaseosas van incluidos o se cobran aparte?"},{"id":"p3","texto":"¿Vendes el trago doble? ¿Cuesta el doble del sencillo o tiene un precio propio?"},{"id":"p4","texto":"¿Qué presentaciones de cerveza vendes (botella, jarra, cubetazo) y cuántas cervezas trae cada una?"},{"id":"p5","texto":"¿Cobras de más por la michelada, la cerveza con limón y sal, o un cóctel con licor premium?"},{"id":"p6","texto":"¿Tienes happy hour, 2x1 u otras promociones? ¿Cómo funcionan?"},{"id":"p7","texto":"¿El precio de tu carta ya incluye el impuesto al consumo y la propina sugerida?"}],"fuente":"docs/plantillas/bar.md"}$json$::jsonb, false, 1)
