:{"lista":"metodo_filtrado"}},{"id":"g_pan","nombre":"Cómo lo quieres","modo":"single","min":0,"max":1,"requerido":false,"fuente":{"lista":"calentar_pan"}},{"id":"g_combo_acomp","nombre":"Acompañante","modo":"single","min":1,"max":1,"requerido":true,"fuente":{"lista":"acompanante_combo"}}],"platos_ejemplo":[{"nombre":"Tinto","categoria":"cafes_calientes","precio":0,"grupos":["g_tamano_corto_largo","g_endulzante"]},{"nombre":"Americano","categoria":"cafes_calientes","precio":0,"grupos":["g_tamano_cafe","g_extras_cafe","g_endulzante"]},{"nombre":"Capuchino","categoria":"cafes_calientes","precio":0,"grupos":["g_tamano_cafe","g_leche","g_sabor","g_extras_cafe"]},{"nombre":"Latte","categoria":"cafes_calientes","precio":0,"grupos":["g_tamano_cafe","g_temperatura","g_leche","g_sabor","g_extras_cafe"]},{"nombre":"Café filtrado de especialidad","categoria":"cafes_calientes","precio":0,"grupos":["g_metodo"]},{"nombre":"Frappé de café","categoria":"cafes_frios","precio":0,"grupos":["g_tamano_cafe","g_leche","g_sabor","g_extras_cafe"]},{"nombre":"Croissant","categoria":"panaderia","precio":0,"grupos":["g_pan"]},{"nombre":"Sándwich","categoria":"sandwiches","precio":0,"grupos":["g_pan"]},{"nombre":"Combo café + acompañante","categoria":"combos","precio":0,"grupos":["g_tamano_cafe","g_leche","g_combo_acomp"]}],"preguntas":[{"id":"p1","texto":"¿Cuántos tamaños de bebida vendes y cómo los llamas (pequeño, mediano, grande, onzas)? ¿Son los mismos para todas las bebidas?"},{"id":"p2","texto":"¿Cobras más por cambiar a leche de avena, almendra u otra leche vegetal? ¿Ese extra cambia según el tamaño?"},{"id":"p3","texto":"¿Cobras aparte los jarabes, el shot extra de café, la crema u otras adiciones?"},{"id":"p4","texto":"¿Vendes el mismo café caliente y frío al mismo precio, o son productos distintos?"},{"id":"p5","texto":"¿Tienes combos de café con pan o postre? ¿El cliente escoge el acompañante o ya viene definido?"},{"id":"p6","texto":"¿Vendes café en grano o molido para llevar? ¿En