io_extra":0}]},{"key":"acompanantes_arabe","nombre":"Acompañantes","items":[{"label":"Papas fritas","precio_extra":0},{"label":"Arroz con almendras","precio_extra":0},{"label":"Tabule","precio_extra":0},{"label":"Ensalada árabe","precio_extra":0},{"label":"Falafel (3 unidades)","precio_extra":0}]},{"key":"bebidas_arabe","nombre":"Bebidas del combo","items":[{"label":"Gaseosa","precio_extra":0},{"label":"Limonada con hierbabuena","precio_extra":0},{"label":"Jugo natural","precio_extra":0},{"label":"Agua","precio_extra":0}]},{"key":"mezze_arabe","nombre":"Entradas para el mezze","items":[{"label":"Hummus","precio_extra":0},{"label":"Baba ganoush","precio_extra":0},{"label":"Tabule","precio_extra":0},{"label":"Kibbe frito","precio_extra":0},{"label":"Hojas de parra rellenas","precio_extra":0},{"label":"Falafel","precio_extra":0},{"label":"Labneh","precio_extra":0},{"label":"Ensalada árabe","precio_extra":0}]},{"key":"tamanos_parrillada_arabe","nombre":"Tamaño de la parrillada","items":[{"label":"Para 2 personas","precio_extra":0},{"label":"Para 4 personas","precio_extra":0},{"label":"Para 6 personas","precio_extra":0}]},{"key":"dulces_arabe","nombre":"Dulces árabes","items":[{"label":"Baklava","precio_extra":0},{"label":"Maamoul","precio_extra":0},{"label":"Basbousa","precio_extra":0},{"label":"Knafe","precio_extra":0},{"label":"Helado casero","precio_extra":0}]}],"grupos_tipicos":[{"id":"g_formato","nombre":"Formato","modo":"single","min":1,"max":1,"requerido":true,"fuente":{"lista":"formatos_arabe"}},{"id":"g_proteina","nombre":"Proteína a elegir","modo":"single","min":1,"max":1,"requerido":true,"fuente":{"lista":"proteinas_arabe"}},{"id":"g_tamano_shawarma","nombre":"Tamaño","modo":"single","min":1,"max":1,"requerido":true,"fuente":{"lista":"tamanos_arabe"}},{"id":"g_salsas","nombre":"Salsas","modo":"multi","min":0,"max":2,"requerido":false,"fuente":{"lista":"salsas_arabe"}},{"id":"g_vegetales","nombre":"Vegetales","modo":"multi","min":0,"max":5,"requerido":false,"fuente":{"lista":"vegetales_arabe"}},{"id":"g_picante","nombre":"Picante","modo":"single","min":0,"max":1,"requerido":false,"fuente":{"lista":"picante_arabe"}},{"id":"g_acompanante","nombre":"Acompañante","modo":"single","min":1,"max":1,"requerido":true,"fuente":{"lista":"acompanantes_arabe"}},{"id":"g_bebida_combo","nombre":"Bebida del combo","modo":"single","min":1,"max":1,"requerido":true,"fuente":{"lista":"bebidas_arabe"}},{"id":"g_mezze","nombre":"Arma tu mezze","modo":"multi","min":3,"max":4,"requerido":true,"fuente":{"lista":"mezze_arabe"}},{"id":"g_carnes_parrillada","nombre":"Carnes de la parrillada","modo":"multi","min":1,"max":3,"requerido":true,"fuente":{"lista":"proteinas_arabe"}},{"id":"g_tamano_parrillada","nombre":"Tamaño de la parrillada","modo":"single","min":1,"max":1,"requerido":true,"fuente":{"lista":"tamanos_parrillada_arabe"}},{"id":"g_dulces","nombre":"Dulces del surtido","modo":"multi","min":2,"max":4,"requerido":true,"fuente":{"lista":"dulces_arabe"}}],"platos_ejemplo":[{"nombre":"Shawarma a elegir","categoria":"shawarmas","precio":0,"grupos":["g_formato","g_proteina","g_tamano_shawarma","g_salsas","g_vegetales","g_picante"]},{"nombre":"Shawarma mixto","categoria":"shawarmas","precio":0,"grupos":["g_formato","g_tamano_shawarma","g_salsas","g_vegetales","g_picante"]},{"nombre":"Shawarma de falafel","categoria":"falafel_vegetarianos","precio":0,"grupos":["g_formato","g_tamano_shawarma","g_salsas","g_vegetales","g_picante"]},{"nombre":"Plato de falafel","categoria":"falafel_vegetarianos","precio":0,"grupos":["g_salsas","g_acompanante"]},{"nombre":"Hummus con pan","categoria":"entradas_frias","precio":0,"grupos":[]},{"nombre":"Tabule","categoria":"entradas_frias","precio":0,"grupos":[]},{"nombre":"Kibbe frito","categoria":"entradas_calientes","precio":0,"grupos":[]},{"nombre":"Plato de kafta","categoria":"platos_fuertes","precio":0,"grupos":["g_acompanante","g_salsas","g_picante"]},{"nombre":"Brocheta a la parrilla","categoria":"platos_fuertes","precio":0,"grupos":["g_proteina","g_acompanante","g_salsas","g_picante"]},{"nombre":"Parrillada árabe","categoria":"parrillada_arabe","precio":0,"grupos":["g_tamano_parrillada","g_carnes_parrillada","g_acompanante","g_salsas"]},{"nombre":"Mezze para compartir","categoria":"mezze_y_combos","precio":0,"grupos":["g_mezze"]},{"nombre":"Combo shawarma","categoria":"mezze_y_combos","precio":0,"grupos":["g_formato","g_proteina","g_salsas","g_acompanante","g_bebida_combo"]},{"nombre":"Surtido de dulces árabes","categoria":"postres_arabes","precio":0,"grupos":["g_dulces"]},{"nombre":"Limonada con hierbabuena","categoria":"bebidas","precio":0,"grupos":[]}],"preguntas":[{"id":"p1","texto":"¿Cómo vendes el shawarma: por tamaño (mini, regular, extra) o por formato (rollo, pita, plato)?"},{"id":"p2","texto":"¿El precio cambia según la proteína, por ejemplo cordero o res frente a pollo?"},{"id":"p3","texto":"¿Vendes el mezze como una tabla de precio fijo donde el cliente elige entradas, o cada entrada se cobra por aparte?"},{"id":"p4","texto":"¿Qué salsas y extras cobras aparte (salsa de ajo, pan adicional) y cuáles van incluidos en el plato?"},{"id":"p5","texto":"¿Vendes dulces árabes por unidad, por peso o por caja?"},{"id":"p6","texto":"¿Qué proteínas ofreces de verdad en tu carta (pollo, res, cordero)?"}],"fuente":"docs/plantillas/comida_arabe.md"}$json$::jsonb, false, 1)
ON CONFLICT (key) DO NOTHING;
